  1666	func findSemanticSymbolsInSQLite(storePath, query string, limit, offset int) ([]semanticRecord, error) {
  1667		db, err := sql.Open("sqlite", storePath)
  1668		if err != nil {
  1669			return nil, err
  1670		}
  1671		defer db.Close()
  1672		literal := strings.ToLower(strings.TrimSpace(query))
  1673		rows, err := db.Query(`SELECT s.id, s.kind, s.name, s.qualified_name, s.file_path, s.start_line, s.end_line, s.signature, s.language, s.stable_id_version
  1674	FROM symbols s
  1675	JOIN symbol_fts f ON f.id = s.id
  1676	WHERE instr(lower(f.text), ?) > 0
  1677	ORDER BY CASE WHEN lower(s.name) = lower(?) THEN 0 WHEN lower(s.qualified_name) = lower(?) THEN 1 ELSE 2 END, s.qualified_name
  1678	LIMIT ? OFFSET ?`, literal, query, query, limit, offset)
  1679		if err != nil {
  1680			return nil, err
  1681		}
  1682		defer rows.Close()
  1683		var results []semanticRecord
  1684		for rows.Next() {
  1685			var record semanticRecord
  1686			record.RecordType = "symbol"
  1687			if err := rows.Scan(&record.ID, &record.Kind, &record.Name, &record.QualifiedName, &record.FilePath, &record.StartLine, &record.EndLine, &record.Signature, &record.Language, &record.StableIDVersion); err != nil {
  1688				return nil, err
  1689			}
  1690			results = append(results, record)
  1691		}
  1692		return results, rows.Err()
  1693	}
  1694	
  1695	func findSemanticSymbols(snapshotPath, query string, limit, offset int) ([]semanticRecord, error) {
  1696		f, err := os.Open(snapshotPath)
  1697		if err != nil {
  1698			return nil, fmt.Errorf("open semantic snapshot: %w", err)
  1699		}
  1700		defer f.Close()
  1701		query = strings.ToLower(strings.TrimSpace(query))
  1702		scanner := newSemanticScanner(f)
  1703		first := true
  1704		var results []semanticRecord
  1705		seen := 0
  1706		for scanner.Scan() {
  1707			if first {
  1708				first = false
  1709				continue
  1710			}
  1711			text := bytes.TrimSpace(scanner.Bytes())
  1712			if len(text) == 0 {
  1713				continue
  1714			}
  1715			var record semanticRecord
  1716			if err := json.Unmarshal(text, &record); err != nil {
  1717				return nil, err
  1718			}
  1719			if record.RecordType != "symbol" {
  1720				continue
  1721			}
  1722			fields := []string{record.Name, record.QualifiedName, record.Signature, record.FilePath}
  1723			for _, field := range fields {
  1724				if strings.Contains(strings.ToLower(field), query) {
  1725					if seen < offset {
  1726						seen++
  1727						break
  1728					}
  1729					results = append(results, record)
  1730					seen++
  1731					break
  1732				}
  1733			}
  1734			if len(results) >= limit {
  1735				break
  1736			}
  1737		}
  1738		return results, scanner.Err()
  1739	}
