  1741	func findSemanticRelationsForSymbolsInSQLite(storePath string, symbols []semanticRecord, limit int) ([]semanticRecord, error) {
  1742		if len(symbols) == 0 {
  1743			return nil, nil
  1744		}
  1745		ids := make([]any, 0, len(symbols)*2)
  1746		placeholders := make([]string, 0, len(symbols))
  1747		for _, symbol := range symbols {
  1748			ids = append(ids, symbol.ID)
  1749			placeholders = append(placeholders, "?")
  1750		}
  1751		db, err := sql.Open("sqlite", storePath)
  1752		if err != nil {
  1753			return nil, err
  1754		}
  1755		defer db.Close()
  1756		args := append(append([]any{}, ids...), ids...)
  1757		args = append(args, limit)
  1758		inClause := strings.Join(placeholders, ",")
  1759		rows, err := db.Query(`SELECT from_id, to_id, type, confidence, reason FROM relations
  1760	WHERE from_id IN (`+inClause+`) OR to_id IN (`+inClause+`)

Chunk ID: a16e7c
Wall time: 0.0000 seconds
Process exited with code 0
Original token count: 2501
Output:
  1760	WHERE from_id IN (`+inClause+`) OR to_id IN (`+inClause+`)
  1761	ORDER BY id LIMIT ?`, args...)
  1762		if err != nil {
  1763			return nil, err
  1764		}
  1765		defer rows.Close()
  1766		var relations []semanticRecord
  1767		for rows.Next() {
  1768			var record semanticRecord
  1769			record.RecordType = "relation"
  1770			if err := rows.Scan(&record.FromID, &record.ToID, &record.Type, &record.Confidence, &record.Reason); err != nil {
  1771				return nil, err
  1772			}
  1773			relations = append(relations, record)
  1774		}
  1775		return relations, rows.Err()
  1776	}
