  1778	func findSemanticRelationsForSymbols(snapshotPath string, symbols []semanticRecord, limit int) ([]semanticRecord, error) {
  1779		if len(symbols) == 0 {
  1780			return nil, nil
  1781		}
  1782		ids := make(map[string]struct{}, len(symbols))
  1783		for _, symbol := range symbols {
  1784			ids[symbol.ID] = struct{}{}
  1785		}
  1786		f, err := os.Open(snapshotPath)
  1787		if err != nil {
  1788			return nil, err
  1789		}
  1790		defer f.Close()
  1791		scanner := newSemanticScanner(f)
  1792		first := true
  1793		var relations []semanticRecord
  1794		for scanner.Scan() {
  1795			if first {
  1796				first = false
  1797				continue
  1798			}
  1799			var record semanticRecord
  1800			if err := json.Unmarshal(bytes.TrimSpace(scanner.Bytes()), &record); err != nil {
  1801				return nil, err
  1802			}
  1803			if record.RecordType != "relation" {
  1804				continue
  1805			}
  1806			_, from := ids[record.FromID]
  1807			_, to := ids[record.ToID]
  1808			if from || to {
  1809				relations = append(relations, record)
  1810				if len(relations) >= limit {
  1811					break
  1812				}
  1813			}
  1814		}
  1815		return relations, scanner.Err()
  1816	}
