  1818	func semanticContextContent(repoDir string, symbols []semanticRecord) []semanticContent {
  1819		var content []semanticContent
  1820		for _, symbol := range symbols {
  1821			if symbol.FilePath == "" || symbol.StartLine <= 0 {
  1822				continue
  1823			}
  1824			clean, err := validateSemanticProviderPath(symbol.FilePath)
  1825			if err != nil {
  1826				continue
  1827			}
  1828			if err := rejectSymlinkPathComponents(repoDir, filepath.FromSlash(clean)); err != nil {
  1829				continue
  1830			}
  1831			text, err := readSemanticContextSnippet(filepath.Join(repoDir, filepath.FromSlash(clean)), symbol.StartLine, symbol.EndLine)
  1832			if err != nil {
  1833				continue
  1834			}
  1835			content = append(content, semanticContent{Path: clean, StartLine: symbol.StartLine, EndLine: symbol.EndLine, Text: text})
  1836		}
  1837		return content
  1838	}
