  1840	func readSemanticContextSnippet(path string, start, end int) (string, error) {
  1841		if start <= 0 {
  1842			return "", errors.New("start line must be positive")
  1843		}
  1844		if end < start {
  1845			end = start
  1846		}
  1847		f, err := os.Open(path)
  1848		if err != nil {
  1849			return "", err
  1850		}
  1851		defer f.Close()
  1852		scanner := bufio.NewScanner(f)
  1853		scanner.Buffer(make([]byte, 0, 64*1024), 256*1024)
  1854		var lines []string
  1855		line := 0
  1856		for scanner.Scan() {
  1857			line++
  1858			if line < start {
  1859				continue
  1860			}
  1861			if line > end {
  1862				break
  1863			}
  1864			lines = append(lines, scanner.Text())
  1865		}
  1866		if err := scanner.Err(); err != nil {
  1867			return "", err
  1868		}
  1869		if len(lines) == 0 {
  1870			return "", errors.New("line range outside file")
  1871		}
  1872		return strings.Join(lines, "\n"), nil
  1873	}
