  1903	func runSemanticGC(ctx context.Context, cmd *cobra.Command, opts Options, target, olderThan string) error {
  1904		cutoff, err := parseAgeCutoff(olderThan, opts.Now().UTC())
  1905		if err != nil {
  1906			return err
  1907		}
  1908		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
  1909		if err != nil {
  1910			return err
  1911		}
  1912		if !local {
  1913			return fmt.Errorf("gc requires a local repository path: %s", target)
  1914		}
  1915		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
  1916		if err != nil {
  1917			return err
  1918		}
  1919		if err := ensureSemanticAuditPathSafe(storage.BrainDir); err != nil {
  1920			return err
  1921		}
  1922		unlock, err := acquireSemanticIndexLock(storage.BrainDir)
  1923		if err != nil {
  1924			return err
  1925		}
  1926		defer unlock()
  1927		manifest, err := loadBrainManifest(storage.BrainDir)
  1928		if err != nil {
  1929			return err
  1930		}
  1931		activeSnapshot := ""
  1932		activeGeneration := ""
  1933		if manifest != nil && manifest.Sources != nil && manifest.Sources.Semantic != nil {
  1934			activeSnapshot = filepath.Clean(filepath.Join(storage.BrainDir, filepath.FromSlash(manifest.Sources.Semantic.SnapshotPath), ".."))
  1935			if manifest.Sources.Semantic.GenerationPath != "" {
  1936				activeGeneration = filepath.Clean(filepath.Join(storage.BrainDir, filepath.FromSlash(manifest.Sources.Semantic.GenerationPath)))
  1937			}
  1938		}
  1939		prunedSnapshots, err := pruneSemanticChildDirs(storage.BrainDir, filepath.Join(semanticDirName, semanticSnapshotsDir), activeSnapshot, cutoff)
  1940		if err != nil {
  1941			return err
  1942		}
  1943		prunedGenerations, err := pruneSemanticChildDirs(storage.BrainDir, filepath.Join(semanticDirName, semanticGenerationsDir), activeGeneration, cutoff)
  1944		if err != nil {
  1945			return err
  1946		}
  1947		fmt.Fprintf(cmd.OutOrStdout(), "pruned semantic snapshots: %d\n", prunedSnapshots)
  1948		fmt.Fprintf(cmd.OutOrStdout(), "pruned semantic generations: %d\n", prunedGenerations)
  1949		return nil
  1950	}
  1951	
  1952	func pruneSemanticChildDirs(brainDir, rootRel, active string, cutoff time.Time) (int, error) {
  1953		if err := rejectExistingSymlinkPathComponents(brainDir, rootRel); err != nil {
  1954			return 0, err
  1955		}
  1956		root := filepath.Join(brainDir, rootRel)
  1957		entries, err := os.ReadDir(root)
  1958		if err != nil {
  1959			if os.IsNotExist(err) {
  1960				return 0, nil
  1961			}
  1962			return 0, err
  1963		}
  1964		pruned := 0
  1965		for _, entry := range entries {
  1966			if !entry.IsDir() {
  1967				continue
  1968			}
  1969			path := filepath.Join(root, entry.Name())
  1970			if active != "" && filepath.Clean(path) == active {
  1971				continue
  1972			}
  1973			if err := rejectSymlinkPathComponents(brainDir, filepath.Join(rootRel, entry.Name())); err != nil {
  1974				return 0, err
  1975			}
  1976			info, err := entry.Info()
  1977			if err != nil {
  1978				continue
  1979			}
  1980			if info.ModTime().Before(cutoff) {
  1981				if err := os.RemoveAll(path); err != nil {
  1982					return 0, err
  1983				}
  1984				pruned++
  1985			}
  1986		}
  1987		return pruned, nil
  1988	}
  1989	
  1990	func parseAgeCutoff(value string, now time.Time) (time.Time, error) {
  1991		value = strings.TrimSpace(value)
  1992		if strings.HasSuffix(value, "d") {
  1993			days, err := strconv.Atoi(strings.TrimSuffix(value, "d"))
  1994			if err != nil || days < 0 {
  1995				return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
  1996			}
  1997			return now.Add(-time.Duration(days) * 24 * time.Hour), nil
  1998		}
  1999		duration, err := time.ParseDuration(value)
  2000		if err != nil {
  2001			return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
  2002		}
  2003		return now.Add(-duration), nil
  2004	}
