  2753	func validateImportedGenerationEntries(root string, source *semanticSourceManifest, generationPath string) error {
  2754		generationRoot := filepath.Join(root, generationPath)
  2755		allowedFiles := map[string]struct{}{}
  2756		for _, rel := range []string{source.StorePath, source.MetricsPath} {
  2757			if rel == "" {
  2758				continue
  2759			}
  2760			clean, err := validateSemanticGenerationFilePath(rel, generationPath, "")
  2761			if err != nil {
  2762				return err
  2763			}
  2764			allowedFiles[filepath.ToSlash(clean)] = struct{}{}
  2765		}
  2766		parseCachePath := ""
  2767		if source.ParseCachePath != "" {
  2768			expectedParseCache := filepath.ToSlash(filepath.Join(generationPath, "parse-cache"))
  2769			if source.ParseCachePath != expectedParseCache {
  2770				return fmt.Errorf("semantic parse_cache_path must be %s: %s", expectedParseCache, source.ParseCachePath)
  2771			}
  2772			clean, err := validateSemanticGenerationFilePath(source.ParseCachePath+"/.placeholder", generationPath, "")
  2773			if err != nil {
  2774				return err
  2775			}
  2776			parseCachePath = strings.TrimSuffix(filepath.ToSlash(clean), "/.placeholder")
  2777		}
  2778		return filepath.WalkDir(generationRoot, func(path string, d os.DirEntry, walkErr error) error {
  2779			if walkErr != nil {
  2780				return walkErr
  2781			}
  2782			if d.IsDir() {
  2783				return nil
  2784			}
  2785			rel, err := filepath.Rel(root, path)
  2786			if err != nil {
  2787				return err
  2788			}
  2789			relSlash := filepath.ToSlash(rel)
  2790			if _, ok := allowedFiles[relSlash]; ok {
  2791				return nil
  2792			}
  2793			if parseCachePath != "" && strings.HasPrefix(relSlash, parseCachePath+"/") {
  2794				return nil
  2795			}
  2796			return fmt.Errorf("bundle contains unreferenced semantic generation entry: %s", relSlash)
  2797		})
  2798	}
