  2800	func validateSemanticSQLiteStore(path string, expectedSymbols, expectedRelations int) error {
  2801		info, err := os.Lstat(path)
  2802		if err != nil {
  2803			return fmt.Errorf("semantic sqlite store missing: %w", err)
  2804		}
  2805		if info.Mode()&os.ModeSymlink != 0 {
  2806			return fmt.Errorf("semantic sqlite store must not be a symlink: %s", path)
  2807		}
  2808		if info.IsDir() {
  2809			return fmt.Errorf("semantic sqlite store must be a file: %s", path)
  2810		}
  2811		db, err := sql.Open("sqlite", path)
  2812		if err != nil {
  2813			return fmt.Errorf("open semantic sqlite store: %w", err)
  2814		}
  2815		defer db.Close()
  2816		var integrity string
  2817		if err := db.QueryRow(`PRAGMA integrity_check`).Scan(&integrity); err != nil {
  2818			return fmt.Errorf("validate semantic sqlite integrity: %w", err)
  2819		}
  2820		if integrity != "ok" {
  2821			return fmt.Errorf("semantic sqlite integrity check failed: %s", integrity)
  2822		}
  2823		symbols, err := semanticSQLiteTableCount(db, "symbols")
  2824		if err != nil {
  2825			return err
  2826		}
  2827		relations, err := semanticSQLiteTableCount(db, "relations")
  2828		if err != nil {
  2829			return err
  2830		}
  2831		if symbols != expectedSymbols {
  2832			return fmt.Errorf("semantic sqlite symbol count %d does not match manifest %d", symbols, expectedSymbols)
  2833		}
  2834		if relations != expectedRelations {
  2835			return fmt.Errorf("semantic sqlite relation count %d does not match manifest %d", relations, expectedRelations)
  2836		}
  2837		return nil
  2838	}
